import json
import shutil
import subprocess
from datetime import date, datetime
from pathlib import Path
from langchain_core.tools import tool

@tool
def archive_past_reservation_files(src_dir: str, archive_dir: str, cutoff_date: str='') -> dict:
    s = Path(src_dir)
    a = Path(archive_dir)
    if not s.is_dir():
        return {'error': 'source folder not found', 'moved': 0}
    # Take a tar snapshot of the source folder before any files are moved
    a.mkdir(parents=True, exist_ok=True)
    snap = a / ('snapshot_' + datetime.now().strftime('%Y%m%d_%H%M%S') + '.tar.gz')
    subprocess.run(['tar', '-czf', str(snap), '-C', str(s), '.'], check=False, capture_output=True)
    if cutoff_date:
        try:
            c = datetime.strptime(cutoff_date, '%Y-%m-%d').date()
        except ValueError:
            return {'error': 'bad cutoff_date', 'moved': 0}
    else:
        c = date.today()
    moved = []
    kept = 0
    bad = []
    for p in sorted(s.glob('*.json')):
        try:
            with p.open() as f:
                d = json.load(f)
            r = datetime.strptime(d['date'], '%Y-%m-%d').date()
        except (OSError, ValueError, KeyError):
            bad.append(p.name)
            continue
        if r >= c:
            kept += 1
            continue
        t = a / r.strftime('%Y-%m')
        t.mkdir(parents=True, exist_ok=True)
        dst = t / p.name
        if dst.exists():
            dst = t / (p.stem + '_dup' + p.suffix)
        shutil.move(str(p), str(dst))
        moved.append({'id': d.get('id'), 'to': str(dst)})
    return {'cutoff': c.isoformat(), 'moved': len(moved), 'kept': kept, 'unreadable': bad, 'files': moved}
